  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B010",
      "proposed_laureates": [
        "Charles L. Bennett",
        "Jean-Loup Puget",
        "Lyman A. Page Jr."
      ],
      "assessment": {
        "nobel_worthiness": "Precision mapping of the microwave background established the detailed empirical basis for modern cosmology; measuring its anisotropies was a field-defining achievement.",
        "attribution": "Bennett, Puget and Page represent major observational and instrumental contributions, though the discovery and mapping depended on large teams and multiple missions.",
        "maturity": "The results have been extensively tested and have anchored cosmological inference for decades.",
        "uncertainties": [
          "The proposed credit is necessarily selective across instruments, missions and a broad international community.",
          "The candidate combines acoustic structure with precision mapping, whose contributions span distinct experiments."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Harald Rose",
        "Knut Urban",
        "Max Haider"
      ],
      "assessment": {
        "nobel_worthiness": "Correcting spherical aberration removed a fundamental limitation in electron microscopy and enabled atomic-scale imaging that reshaped materials research.",
        "attribution": "Rose's theoretical design and the experimental development by Urban and Haider form a compelling, complementary attribution.",
        "maturity": "The correction has been implemented and validated across instruments and continues to deliver routine scientific results.",
        "uncertainties": [
          "The boundary between the key correction, its engineering realization and subsequent instrument development should be carefully defined."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B015",
      "proposed_laureates": [
        "Fabiola Gianotti",
        "Michel Della Negra",
        "Peter Jenni"
      ],
      "assessment": {
        "nobel_worthiness": "The experimental discovery of the Higgs boson confirmed a central prediction of particle physics and completed a major part of the Standard Model.",
        "attribution": "These leaders represent the ATLAS and CMS experiments, but the result depended on thousands of collaborators; choosing individual experimental laureates is difficult.",
        "maturity": "The signal has been confirmed and its properties studied in many channels, making the discovery exceptionally secure.",
        "uncertainties": [
          "Credit for an experiment-wide discovery is difficult to reduce to a few individuals.",
          "The Higgs mechanism already received Nobel recognition for its theoretical foundation, which may affect the case for a separate experimental prize."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Eugene S. Polzik",
        "H. Jeff Kimble",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Light-matter interfaces and quantum memories made coherent storage and retrieval of quantum states experimentally credible and helped lay foundations for quantum networks.",
        "attribution": "Polzik, Kimble and Lukin represent important experimental and conceptual advances, while the field's progress involved many groups and approaches.",
        "maturity": "Quantum memories have been repeatedly demonstrated and improved, although network-scale performance and practical deployment remain active challenges.",
        "uncertainties": [
          "The candidate spans several related but distinct advances, so the precise contribution deserving recognition needs delimiting.",
          "Long-term system reliability and scaling remain unsettled."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B045",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have advanced precision measurement to extraordinary levels and opened new tests of fundamental physics and applications in geodesy.",
        "attribution": "Katori and Ye are central to the lattice-clock concept and its experimental realization, with clear individual contributions.",
        "maturity": "Independent implementations and sustained gains in accuracy and stability provide strong confirmation; the technology is still advancing.",
        "uncertainties": [
          "The long-term significance of applications beyond timekeeping is still developing."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Heino Falcke",
        "J. Anton Zensus",
        "Sheperd S. Doeleman"
      ],
      "assessment": {
        "nobel_worthiness": "Horizon-scale imaging turned a long-standing prediction about black holes into direct observational evidence and established a remarkable new capability in radio interferometry.",
        "attribution": "Falcke's scientific framing, Zensus's leadership in millimetre VLBI and Doeleman's instrumental and observational leadership make a plausible trio, though the result was collective.",
        "maturity": "The first image has been followed by further observations and independent analysis, but the observing program remains relatively young.",
        "uncertainties": [
          "The image is an indirect reconstruction from sparse interferometric data, requiring careful characterization of systematic and modeling limits.",
          "The scale of the collaboration makes individual attribution challenging."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "John D. Joannopoulos",
        "Philip St.J. Russell"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic band gaps and photonic crystals introduced powerful control of light propagation and stimulated broad developments in optics and photonics.",
        "attribution": "Yablonovitch and John established core concepts, while Russell's photonic-crystal fibre work provided a distinct influential realization; the candidate combines related strands.",
        "maturity": "The underlying physics is well established and has supported extensive experimental and technological development.",
        "uncertainties": [
          "The scope includes several architectures and advances, and the division of credit among the proposed names depends on where the discovery is defined."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B036",
      "proposed_laureates": [
        "Claudio Pellegrini",
        "Jörg Rossbach",
        "Tetsuya Ishikawa"
      ],
      "assessment": {
        "nobel_worthiness": "X-ray free-electron lasers based on self-amplified spontaneous emission created unprecedented coherent, intense X-ray pulses and enabled new measurements of ultrafast and nanoscale processes.",
        "attribution": "Pellegrini's accelerator concept, Rossbach's development and Ishikawa's facility leadership represent important contributions, though many teams built and operated the machines.",
        "maturity": "Several facilities have demonstrated reproducible scientific output over many years, and the method has become a major research tool.",
        "uncertainties": [
          "Credit for a large accelerator and facility program is distributed across theory, engineering, construction and scientific operation."
        ]
      }
    }
  ]
}
